// ************
// Types
// ************

import '@dev.hiconic/gm_descriptive-model';
import '@dev.hiconic/gm_basic-resource-model';
import '@dev.hiconic/gm_gm-core-api';

import { T } from '@dev.hiconic/hc-js-base';

export declare namespace meta {
	const groupId: string;
	const artifactId: string;
	const version: string;
}

export import AdaptiveIcon = T.com.braintribe.model.resource.AdaptiveIcon;
export import Icon = T.com.braintribe.model.resource.Icon;
export import SimpleIcon = T.com.braintribe.model.resource.SimpleIcon;

declare module '@dev.hiconic/hc-js-base' {

	namespace T.com.braintribe.model.resource {

		const AdaptiveIcon: hc.reflection.EntityType<AdaptiveIcon>;
		type AdaptiveIcon = Icon &
		  Entity<"com.braintribe.model.resource.AdaptiveIcon", {
			representations: set<Resource>;
		}>;

		const Icon: hc.reflection.EntityType<Icon>;
		type Icon = T.com.braintribe.model.descriptive.HasName &
		  Entity<"com.braintribe.model.resource.Icon">;

		const SimpleIcon: hc.reflection.EntityType<SimpleIcon>;
		type SimpleIcon = Icon &
		  Entity<"com.braintribe.model.resource.SimpleIcon", {
			image: Resource;
		}>;

	}

}
